<script setup> import AdminLayout from "@/Layouts/AdminLayout.vue"; import { Head } from "@inertiajs/vue3"; defineProps({ rmas: Object }); </script> <template> <Head title="Returns & RMAs" /> <AdminLayout> <div class="p-8"><div class="sm:flex sm:items-center"><div class="sm:flex-auto"><h1 class="text-2xl font-bold text-gray-900">Return Merchandise Authorizations (RMAs)</h1><p class="mt-2 text-sm text-gray-700">Manage client product returns, defective items, and stock restorations.</p></div></div><div class="mt-8 bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden"><table class="min-w-full divide-y divide-gray-200"><thead class="bg-gray-50"><tr><th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">RMA ID</th><th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Client</th><th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Invoice</th><th class="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th><th class="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Refund Amount</th></tr></thead><tbody class="bg-white divide-y divide-gray-200"><tr v-if="rmas.data.length === 0"><td colspan="5" class="px-6 py-12 text-center text-sm text-gray-500 font-medium">No RMA requests found.</td></tr><tr v-for="rma in rmas.data" :key="rma.id"><td class="px-6 py-4 whitespace-nowrap text-sm font-bold text-gray-900">RMA-{{ rma.id.toString().padStart(5, "0") }}</td><td class="px-6 py-4 whitespace-nowrap text-sm text-gray-500">{{ rma.user.name }}</td><td class="px-6 py-4 whitespace-nowrap text-sm text-blue-600 font-medium">INV-{{ rma.invoice.quote_id.toString().padStart(5, "0") }}</td><td class="px-6 py-4 whitespace-nowrap"><span class="px-2.5 py-1 text-xs font-bold rounded-full border bg-yellow-100 text-yellow-800 border-yellow-200 uppercase">{{ rma.status }}</span></td><td class="px-6 py-4 white